    if(mapping){const stamp=importMappingStamp(source,schema);if(mapping.header!==stamp.header||mapping.schema!==stamp.schema)throw Error('名单表头或字段定义已变化，请重新配置列映射。');if(mapping.keys.some(key=>!key))throw Error('请为每个导入列选择业务字段，或明确选择忽略此列。');const mapped=mapping.keys.filter(key=>key!==ignoredImportColumn);if(!mapped.length)throw Error('请至少映射一个业务字段。');if(new Set(mapped).size!==mapped.length)throw Error('同一业务字段不能对应多个导入列。');for(const field of schema)if(field.required&&!mapped.includes(field.key))throw Error('缺少必填字段映射：'+field.label);if(source.slice(1).some(row=>row.length>source[0].length))throw Error('名单数据超出表头列数，请补齐表头或修正名单。');const indexes=mapping.keys.map((key,index)=>({key,index})).filter(item=>item.key!==ignoredImportColumn);const projected=source.slice(1).map((row,index)=>{const cells=indexes.map(item=>row[item.index]??'');if(row.some(cell=>String(cell).trim())&&!cells.some(cell=>String(cell).trim()))throw Error('第'+(index+2)+'行未提供可导入字段，请补齐必填数据或移除该行。');return cells;});table=[indexes.map(item=>item.key),...projected];}
