  async function readFile(file){
    if(dialog?.kind!=='import'||!file||dialog.busy||dialog.pending)return;const d=dialog;invalidateImport(true);const version=(d.fileReadVersion||0)+1;d.fileReadVersion=version;d.fileReadText=value('fnw-import-text');importFileReadPending(d,true);dialogError('正在读取文件，请等待读取完成后检查名单。');
    try{const result=await root.DImportFiles.readFile(file);if(!currentImportFileRead(d,version))return;if(value('fnw-import-text')!==d.fileReadText){cancelImportFileRead(d);invalidateImport(true);dialogError('已保留手工编辑的名单，未应用读取结果，请重新检查。');return;}importFileReadPending(d,false);const input=root.document.getElementById('fnw-import-text');if(!input)return;input.value=result.text;invalidateImport(true);dialogError('');}
    catch(error){if(!currentImportFileRead(d,version))return;importFileReadPending(d,false);if(value('fnw-import-text')!==d.fileReadText){cancelImportFileRead(d);invalidateImport(true);dialogError('已保留手工编辑的名单，请重新检查。');return;}dialogError(error.message);}
    finally{if(currentImportFileRead(d,version))importFileReadPending(d,false);}
  }
