    const key=contextKey();let contexts=ids.map(id=>call('arrangementContext',id));if(contexts.some(ret=>ret.status!=='success'))return feedback=contexts.find(ret=>ret.status!=='success'),refresh();let details=ids.map(id=>call('detail',id));if(details.some(ret=>ret.status!=='success'))return feedback=details.find(ret=>ret.status!=='success'),refresh();
    if(details.some(ret=>recordMethod(ret.data)==='AI')){const ready=await prepare();if(key!==contextKey())return;if(!ready)return refresh();contexts=ids.map(id=>call('arrangementContext',id));if(contexts.some(ret=>ret.status!=='success'))return feedback=contexts.find(ret=>ret.status!=='success'),refresh();details=ids.map(id=>call('detail',id));if(details.some(ret=>ret.status!=='success'))return feedback=details.find(ret=>ret.status!=='success'),refresh();}
