    const people=(first.people||[]).filter(p=>data.every(c=>(c.people||[]).some(x=>x.accountId===p.accountId))),scenes=(first.aiScenes||[]).filter(scene=>data.every(c=>(c.aiScenes||[]).some(x=>String(x.id)===String(scene.id))));const content='<p class="fnw-note">'+e(records.length+' 条业务 · '+tenantName(first.tenantId)+' · '+(methods[first.method]||'当前安排'))+'</p><div class="fnw-form-grid">'+(first.method==='AI'?field('AI呼叫场景 <em>*</em>','<select id="fnw-assign-scene">'+selectOptions(scenes,data.every(c=>c.aiSceneId===first.aiSceneId)?first.aiSceneId:'','id','name','请选择本租户AI场景')+'</select>'):'')+field('跟进人 <em>*</em>','<select id="fnw-account">'+selectOptions(people,data.every(c=>c.followupAccountId===first.followupAccountId)?first.followupAccountId:'','accountId','name','请选择跟进人')+'</select>')+'</div><p class="field-hint">'+(first.method==='MANUAL'?'人工跟进人须具备本租户电话资格，这里仍只选择人员。通常由跟进人本人拨打；管理员以本人有效坐席实际办理时，责任跟进人不自动改变。':'只安排业务责任；实际接听和系统归档主体按执行事实分别记录。')+'</p>'+((first.unavailablePeople||[]).length?'<details class="fnw-note"><summary>暂不可分配的人员及原因</summary>'+first.unavailablePeople.map(person=>'<p>'+e(person.name||person.accountId)+'：'+e(person.reason||'电话作业资格未满足')+'</p>').join('')+'</details>':'');openDialog('安排跟进人',content,'assign',records[0],{records,contexts:data});
