    let records=details.map(ret=>ret.data);if(records.some(row=>!writable(row)||!isFourNodeRecord(row))){feedback={status:'failed',message:'请选择本租户当前有权办理的四节点业务。'};return refresh();}
    const method=recordMethod(records[0]);if(!['AI','PREDICTIVE'].includes(method)||records.some(row=>recordMethod(row)!==method)){feedback={status:'failed',message:'批量发起只支持同组AI或预外呼；人工业务由本人逐条办理。'};return refresh();}
    if(method==='AI'){const ready=await prepare();if(key!==contextKey())return false;if(!ready)return refresh();}
    if(key!==contextKey())return false;details=ids.map(id=>call('detail',id));if(details.some(ret=>ret.status!=='success')){feedback=details.find(ret=>ret.status!=='success');return refresh();}records=details.map(ret=>ret.data);
    const contexts=ids.map(id=>call('startContext',id));if(contexts.some(ret=>ret.status!=='success')){feedback=contexts.find(ret=>ret.status!=='success');return refresh();}
    const first=contexts[0].data;if(!first.assignmentGroupKey||contexts.some(ret=>ret.data.assignmentGroupKey!==first.assignmentGroupKey)){feedback={status:'failed',message:'请选择同一负责租户、业务分类、办理模式、当前节点、方式及AI场景的业务，分组发起。'};return refresh();}
    const rowsToShow=records.map((row,index)=>({...row,arrangementContext:contexts[index].data}));
