  function editingControl(field,raw,prefix,handler){const id=prefix+'-'+field.key,change=handler+'('+e(JSON.stringify(field.key))+')';if(field.type==='interface')return '<input readonly value="'+e(optionValue(field,raw))+'"><small>结构化来源不能手工替代，请先由有权入口补齐。</small>';if(field.type==='boolean')return '<select id="'+e(id)+'" onchange="'+change+'"><option value="">未提供／清空</option><option value="true"'+(raw===true?' selected':'')+'>是</option><option value="false"'+(raw===false?' selected':'')+'>否</option></select>';if(['select','multiselect'].includes(field.type))return '<select id="'+e(id)+'"'+(field.type==='multiselect'?' multiple':'')+' onchange="'+change+'"><option value="">请选择</option>'+(field.options||[]).filter(option=>option.enabled!==false||(Array.isArray(raw)?raw:[raw]).includes(option.id)).map(option=>'<option value="'+e(option.id)+'"'+((Array.isArray(raw)?raw:[raw]).includes(option.id)?' selected':'')+(option.enabled===false?' disabled':'')+'>'+e(option.label)+'</option>').join('')+'</select>';if(field.type==='datetime'&&typeof raw==='string'&&/(Z|[+-]\d{2}:?\d{2})$/.test(raw)){const at=root.DListOrder?.parse(raw);if(at!==null&&at!==undefined)raw=new Date(at+8*3600000).toISOString().slice(0,16);}const type={number:'number',date:'date',datetime:'datetime-local',phone:'tel'}[field.type]||'text';return field.type==='textarea'?'<textarea id="'+e(id)+'" oninput="'+change+'">'+e(raw??'')+'</textarea>':'<input id="'+e(id)+'" type="'+type+'" value="'+e(raw??'')+'" oninput="'+change+'">';}
