  function reclassifyTarget(){const d=dialog;if(d?.kind!=='reclassify')return;if(d.targetCategoryId&&d.reclassContext)d.reclassDrafts.set(d.targetCategoryId,{values:reclassificationValues(d),provided:[...(d.reclassProvided||[])]});const target=value('fnw-reclass-category'),ret=call('reclassifyContext',d.row.recordId,target);d.preview=null;d.targetCategoryId=target;const host=root.document.getElementById('fnw-reclass-fields'),preview=root.document.getElementById('fnw-reclass-preview');if(preview)preview.innerHTML='';if(ret.status!=='success'){dialogError(ret.message);if(host)host.innerHTML=notice(ret);d.reclassContext=null;return;}d.reclassContext=ret.data;const saved=d.reclassDrafts.get(target);d.reclassValues=clone(saved?.values||ret.data.values||{});d.reclassProvided=new Set(saved?.provided||[]);if(host)host.innerHTML='<div class="fnw-form-grid">'+targetFields(ret.data).map(field=>fieldMarkupForTarget(field,d.reclassValues)).join('')+'</div><p class="field-hint">仅复用稳定字段身份相同的当前值；新字段、同名或同业务编码字段不会猜配。缺少目标必填资料须补齐。</p>'+((ret.data.issues||[]).length?'<p class="form-error">'+e(ret.data.issues.join('；'))+'</p>':'');dialogError('');}
