  function openContactPolicy(){const ret=call('contactPolicyContext');if(ret.status!=='success'){feedback=ret;return refresh();}const data=ret.data||{};if(data.canManage!==true||!writable()){feedback={status:'failed',message:'仅本租户具备维护权限的管理员可以维护联系协调。'};return refresh();}const policy=data.policy||{},categories=(data.categories||[]).map(category=>({...category,categoryId:category.categoryId||category.id,name:category.name||category.label||category.categoryName||category.categoryId||category.id})),priorities=new Map((policy.categoryPriorities||[]).map(row=>[row.categoryId,row.priority]));openDialog('联系协调设置','<p class="fnw-note">本租户同一规范化号码只允许一个有效呼出安排，此限制始终生效。排队、执行、未知或重试未结束前不释放；完成内容填写不伪装呼叫终态。不同业务仍保留独立身份。</p><div class="fnw-form-grid">'+field('最短联系间隔（分钟）','<input id="fnw-policy-interval" type="number" min="0" step="1" value="'+e(policy.minimumIntervalMinutes||0)+'">','0表示不启用额外间隔限制。')+field('每号码每日实际拨打上限','<input id="fnw-policy-limit" type="number" min="0" step="1" value="'+e(policy.dailyDialLimit||0)+'">','0表示不启用额外每日上限；按北京时间自然日和真实拨打事实计数。')+'</div><h3>业务联系优先级</h3><p class="field-hint">数值越大越优先；同号已有更高优先级的已安排业务时先办理该项。同级按等待先后处理，不抢占正在执行的安排，不自动起呼或自动续拨受限项。</p>'+table([{key:'name',label:'业务分类'},{key:'categoryId',label:'优先级',render:id=>'<input type="number" min="0" step="1" id="fnw-policy-priority-'+e(id)+'" value="'+e(priorities.get(id)??0)+'">'}],categories),'contactPolicy',null,{policyRevision:data.revision,categories,submitLabel:'保存本租户联系协调'});}
