  function openCorrection(id){const ret=call('detail',id);if(ret.status!=='success')return feedback=ret,refresh();const row=ret.data,fields=currentDefinitions(row);openDialog('更正当前有效资料','<p class="fnw-note">只更新明确修改的当前值并留更正来源；原始导入证据、正式跟进快照和已完成流转保持原貌。</p><div class="fnw-form-grid">'+fields.map(field=>fieldMarkup(field,row)).join('')+'</div>'+field('更正原因 <em>*</em>','<textarea id="fnw-reason" required></textarea>'),'correctValues',row,{fields,provided:new Set(),submitLabel:'确认更正当前值'});}
