    const data=ctx.data||{},people=data.people||data.accounts||[],request=(data.requests||[]).find(row=>row.requestId===requestId);
    if(data.canHandoff!==true){feedback={status:'failed',message:'当前仅有此请求的核对资格，没有移交核对责任资格。'};return refresh();}
